package com.axplatform.sheet;

import com.axplatform.common.Problem;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.zip.*;
import static org.assertj.core.api.Assertions.*;

class WorkbookRulesTest {
    static Map<String,Object> table(String value){return Map.of("columns",List.of(Map.of("id","c1","label","항목","type","TEXT","unit","","width",160)),"rows",List.of(List.of(value)),"rowIds",List.of("r1"));}
    static Map<String,Object> entry(String id,String name,Map<String,Object> data){return Map.of("id",id,"name",name,"data",data,"sourceAssetIds",List.of());}
    static Map<String,Object> book(List<Map<String,Object>> sheets){return Map.of("format","AX_WORKBOOK_1","activeSheetId",sheets.get(0).get("id"),"sheets",sheets);}
    @Test void legacyDataAndStableRowIdsSurviveNormalization(){var old=table("00123");var book=WorkbookRules.normalize(old);assertThat(WorkbookRules.data(book,"sheet1")).isEqualTo(old);assertThat(WorkbookRules.normalize(book)).isEqualTo(book);}
    @Test void replacingTargetKeepsOtherSheetsAndSourceMetadata(){var original=WorkbookRules.normalize(book(List.of(entry("a","매출",table("001")),entry("b","재고",table("002")))));var next=WorkbookRules.replace(original,"b",table("003"));assertThat(WorkbookRules.data(next,"a")).isEqualTo(table("001"));assertThat(WorkbookRules.data(next,"b")).isEqualTo(table("003"));assertThat(WorkbookRules.data(original,"b")).isEqualTo(table("002"));assertThatThrownBy(()->WorkbookRules.replace(original,"removed",table("x"))).isInstanceOf(Problem.class).hasMessageContaining("삭제");}
    @Test void sheetNamesAndLimitsRejectAmbiguousWorkbooks(){for(String name:List.of("", "a/b","a\\b","a:b","a?b","[a]","'a","a'","a\nb","a".repeat(32)))assertThatThrownBy(()->WorkbookRules.name(name)).isInstanceOf(Problem.class);assertThatThrownBy(()->WorkbookRules.normalize(book(List.of(entry("a","Sales",table("1")),entry("b","sales",table("2")))))).isInstanceOf(Problem.class);assertThatThrownBy(()->WorkbookRules.normalize(book(java.util.stream.IntStream.range(0,21).mapToObj(i->entry("s"+i,"시트"+i,SheetRules.empty())).toList()))).isInstanceOf(Problem.class);}
    @Test void blankSheetRemovalRequiresSchemaAndDeletePermissions(){var before=WorkbookRules.normalize(book(List.of(entry("a","A",SheetRules.empty()),entry("b","B",SheetRules.empty()))));var after=WorkbookRules.normalize(book(List.of(entry("a","A",SheetRules.empty()))));assertThat(WorkbookRules.requiredActions(before,after)).contains("workspace.sheet.schema.update","workspace.sheet.rows.delete");}
    @Test void allSheetsExportAndTemplateClearsEveryRowsAndSources() throws Exception {var original=WorkbookRules.normalize(book(List.of(entry("a","매출 & 정산",table("001")),entry("b","재고",table("002")),entry("c","빈 시트",SheetRules.empty()))));var reports=reports(XlsxWriter.workbookBytes(original));assertThat(reports).hasSize(3);assertThat(reports.get(0).get("sheetName")).isEqualTo("매출 & 정산");assertThat(reports.get(1).get("rows")).isEqualTo(List.of(List.of("002")));assertThat(reports.get(2).get("status")).isEqualTo("EMPTY");var blank=WorkbookRules.template(original);for(var s:WorkbookRules.sheets(blank)){assertThat((List<?>)WorkbookRules.data(blank,(String)s.get("id")).get("rows")).isEmpty();assertThat((List<?>)s.get("sourceAssetIds")).isEmpty();}assertThat(WorkbookRules.data(original,"a").get("rows")).isEqualTo(List.of(List.of("001")));}
    @Test void errorsAndMissingFormulaCacheBlockOnlyTheirOwnSheets() throws Exception {var list=reports(fixture(List.of("<row r='1'><c r='A1' t='inlineStr'><is><t>값</t></is></c></row><row r='2'><c r='A2'><v>12</v></c></row>","<row r='1'><c r='A1'><f>1+1</f></c></row>","<row r='1'><c r='B1' t='e'><v>#REF!</v></c></row>"),Map.of(),false));assertThat(list.stream().map(s->s.get("status"))).containsExactly("READY","BLOCKED","BLOCKED");assertThat(list.get(1).get("issues").toString()).contains("FORMULA_NO_CACHE","A1");assertThat(list.get(2).get("issues").toString()).contains("CELL_ERROR","B1=#REF!");}
    @Test void cachedFormulasAreValuesWithExplicitWarningAndHiddenSheetsAreMarked() throws Exception {var list=reports(fixture(List.of("<row r='1'><c r='A1' t='inlineStr'><is><t>합계</t></is></c></row><row r='2'><c r='A2'><f>'시트2'!A2</f><v>42</v></c></row>"),Map.of(),true));assertThat(list.get(0).get("rows")).isEqualTo(List.of(List.of("42")));assertThat(list.get(0).get("visibility")).isEqualTo("hidden");assertThat(list.get(0).get("issues").toString()).contains("FORMULA_VALUES","HIDDEN_SHEET");}
    @Test void chartOnlyAndMergedCellsExplainHowToRecover() throws Exception {var list=reports(fixture(List.of("","<row r='1'><c r='A1'><v>1</v></c></row>"),Map.of(0,"<drawing r:id='draw1'/>",1,"<mergeCells><mergeCell ref='A1:B2'/></mergeCells>"),false));assertThat(list.get(0).get("status")).isEqualTo("BLOCKED");assertThat(list.get(0).get("issues").toString()).contains("DRAWING_WITHOUT_VALUES","원본 데이터");assertThat(list.get(1).get("issues").toString()).contains("MERGED_CELLS","A1:B2");}
    @Test void unsupportedEncryptionAndOversizedHeadersAreNotSilentlyChanged(){assertThatThrownBy(()->SheetImport.readWorkbook(new byte[]{1,2,3},"locked.xlsx","UTF-8")).isInstanceOf(Problem.class).hasMessageContaining("암호");assertThatThrownBy(()->SheetImport.readWorkbook(("x".repeat(101)+"\n1").getBytes(StandardCharsets.UTF_8),"long.csv","UTF-8")).isInstanceOf(Problem.class).hasMessageContaining("100자");assertThatThrownBy(()->SheetImport.readWorkbook(new byte[]{1},"old.xls","UTF-8")).isInstanceOf(Problem.class).hasMessageContaining("XLSX");}
    @SuppressWarnings("unchecked") static List<Map<String,Object>> reports(byte[] bytes){return (List<Map<String,Object>>)SheetImport.readWorkbook(bytes,"test.xlsx","UTF-8").get("sheets");}
    static byte[] fixture(List<String> rows,Map<Integer,String> tails,boolean hidden) throws Exception {var output=new ByteArrayOutputStream();try(var zip=new ZipOutputStream(output)){StringBuilder wb=new StringBuilder("<workbook xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main' xmlns:r='http://schemas.openxmlformats.org/officeDocument/2006/relationships'><sheets>"),rels=new StringBuilder("<Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'>");for(int i=0;i<rows.size();i++){int n=i+1;wb.append("<sheet name='시트"+n+"' sheetId='"+n+"' r:id='r"+n+"'"+(hidden?" state='hidden'":"")+"/>");rels.append("<Relationship Id='r"+n+"' Type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet' Target='worksheets/sheet"+n+".xml'/>");write(zip,"xl/worksheets/sheet"+n+".xml","<worksheet xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main' xmlns:r='http://schemas.openxmlformats.org/officeDocument/2006/relationships'><sheetData>"+rows.get(i)+"</sheetData>"+tails.getOrDefault(i,"")+"</worksheet>");}write(zip,"xl/workbook.xml",wb+"</sheets></workbook>");write(zip,"xl/_rels/workbook.xml.rels",rels+"</Relationships>");}return output.toByteArray();}
    static void write(ZipOutputStream zip,String path,String text)throws Exception{zip.putNextEntry(new ZipEntry(path));zip.write(text.getBytes(StandardCharsets.UTF_8));zip.closeEntry();}
}
